SELECT binding.employee_id
FROM employee_source_binding binding
WHERE binding.deli_attendance_source_id = #{sourceId}
  AND binding.effective_to IS NULL
  AND (
        binding.deli_user_id = #{deliPersonId}
        OR binding.deli_ext_id = #{deliPersonId}
  )
ORDER BY binding.employee_id
LIMIT 1

SELECT source.company_id
FROM attendance_source source
WHERE source.attendance_source_id = #{sourceId}

SELECT source.display_name
FROM attendance_source source
WHERE source.attendance_source_id = #{sourceId}

mapper.insert:
INSERT INTO employee_source_binding (
    binding_id, employee_id, deli_user_id, deli_ext_id, deli_employee_num,
    deli_attendance_source_id, binding_status, effective_from,
    effective_to, source, confirmation_ref, deli_row_version,
    deli_confirmed_by, deli_confirmed_at, deli_change_reason
) VALUES (
    #{bindingId}, #{employeeId}, #{deliUserId}, #{deliUserId},
    #{targetEmployeeNumber}, #{sourceId}, 'CONFIRMED', #{effectiveFrom},
    NULL, 'DELI', #{confirmationRef}, 1, #{actorId}, #{at}, #{reason}
)

INSERT INTO deli_employee_binding_revision (
    deli_employee_binding_revision_id, binding_id, attendance_source_id,
    employee_id, deli_ext_id, deli_user_id, revision_action,
    binding_row_version, confirmation_ref, changed_by, changed_at,
    change_reason
) VALUES (
    #{revisionId}, #{bindingId}, #{sourceId}, #{employeeId},
    #{deliUserId}, #{deliUserId}, 'CONFIRMED', 1, #{confirmationRef},
    #{actorId}, #{at}, #{reason}
)
